function Eyebrow({ children }: { children: React.ReactNode }) {
  return <p className="mb-4 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.22em] text-amber-600"><span className="h-px w-8 bg-amber-600" />{children}</p>;
}

function PageWrap({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <div className={`min-h-screen bg-background text-foreground ${className}`}>{children}</div>;
}

function Header({ locale, setLocale }: { locale: Locale; setLocale: (locale: Locale) => void }) {
  const [location, setLocation] = useLocation();
  const [menuOpen, setMenuOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchCategory, setSearchCategory] = useState("Tout");
  const { theme, setTheme } = useTheme();
  const { user, isAuthenticated, logout } = useAuth();
  const copy = translations[locale].ui;
  const navItems = [
    { label: copy.home, href: "/" },
    { label: copy.nav[0], href: "/#services" },
    { label: copy.nav[1], href: "/etudes" },
    { label: copy.nav[2], href: "/partenaires" },
    { label: copy.nav[3], href: "/#about" },
  ];
  const searchResults = useMemo(() => {
    const normalized = searchQuery.trim().toLowerCase();
    if (!normalized) return [];
    const serviceResults = services
      .filter(service => searchCategory === "Tout" || searchCategory === "Services")
      .filter(service => `${service.label} ${service.description} ${service.outcomes.join(" ")}`.toLowerCase().includes(normalized))
      .map(service => ({ type: "Service", title: service.label, detail: service.description, href: `/services/${service.slug}` }));
    const studyResults = programs
      .filter(program => searchCategory === "Tout" || searchCategory === "Études")
      .filter(program => `${program.university} ${program.field} ${program.city} ${program.country}`.toLowerCase().includes(normalized))
      .map(program => ({ type: "Étude", title: program.field, detail: `${program.university} · ${program.city}`, href: "/etudes" }));
    return [...serviceResults, ...studyResults].slice(0, 6);
  }, [searchCategory, searchQuery]);

  useEffect(() => {
    const handleShortcut = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setSearchOpen(true);
      }
      if (event.key === "Escape") setSearchOpen(false);
    };
    window.addEventListener("keydown", handleShortcut);
    return () => window.removeEventListener("keydown", handleShortcut);
  }, []);

  const go = (href: string) => {
    setMenuOpen(false);
    setSearchOpen(false);
    setSearchQuery("");
    if (href.startsWith("/#")) {
      setLocation("/");
      window.setTimeout(() => document.getElementById(href.slice(2))?.scrollIntoView({ behavior: "smooth" }), 50);
    } else {
      setLocation(href);
    }
  };

  return (
    <header className="sticky top-0 z-50 border-b border-border/70 bg-background/88 backdrop-blur-xl">
      <div className="container flex h-[74px] items-center justify-between gap-5">
        <BrandMark />
        <nav className="hidden items-center gap-7 lg:flex" aria-label="Navigation principale">
          {navItems.map(item => <button key={item.href} onClick={() => go(item.href)} className="text-[13px] font-semibold text-muted-foreground transition-colors hover:text-foreground">{item.label}</button>)}
        </nav>
        <div className="hidden items-center gap-2 lg:flex">
          <div className="relative">
            <button onClick={() => setSearchOpen(prev => !prev)} className={`flex h-9 items-center gap-2 rounded-full border px-3 text-xs font-semibold transition ${searchOpen ? "border-amber-300 bg-amber-50 text-amber-700 dark:border-blue-800 dark:bg-[#27302b]/40 dark:text-blue-200" : "border-border bg-card text-muted-foreground hover:text-foreground"}`} aria-expanded={searchOpen} aria-label="Ouvrir la recherche">
              <Search className="size-3.5" />
              <span>{copy.search}</span>
              <kbd className="hidden rounded bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground xl:inline">⌘K</kbd>
            </button>
            {searchOpen && <div className="absolute right-0 top-12 z-[70] w-[360px] rounded-2xl border border-border bg-card p-3 shadow-2xl shadow-slate-950/10">
              <div className="flex items-center gap-2 rounded-xl border border-input bg-background px-3"><Search className="size-4 text-muted-foreground" /><input autoFocus value={searchQuery} onChange={event => setSearchQuery(event.target.value)} placeholder="Services, universités, domaines..." className="h-11 min-w-0 flex-1 bg-transparent text-sm outline-none" /></div>
              <div className="mt-3 flex gap-1"><button onClick={() => setSearchCategory("Tout")} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${searchCategory === "Tout" ? "bg-amber-600 text-white" : "bg-muted text-muted-foreground"}`}>Tout</button><button onClick={() => setSearchCategory("Services")} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${searchCategory === "Services" ? "bg-amber-600 text-white" : "bg-muted text-muted-foreground"}`}>Services</button><button onClick={() => setSearchCategory("Études")} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${searchCategory === "Études" ? "bg-amber-600 text-white" : "bg-muted text-muted-foreground"}`}>Études</button></div>
              {searchQuery.trim() && <div className="mt-3 border-t border-border pt-2">{searchResults.length ? searchResults.map(result => <button key={`${result.type}-${result.title}`} onClick={() => go(result.href)} className="flex w-full items-start gap-3 rounded-xl p-3 text-left transition hover:bg-muted"><span className="mt-0.5 grid size-7 place-items-center rounded-lg bg-amber-50 text-amber-600 dark:bg-amber-500/10"><Search className="size-3.5" /></span><span className="min-w-0 flex-1"><span className="block text-xs font-bold uppercase tracking-[0.12em] text-amber-600">{result.type}</span><span className="mt-1 block truncate text-sm font-semibold">{result.title}</span><span className="mt-1 block truncate text-xs text-muted-foreground">{result.detail}</span></span><ChevronRight className="mt-2 size-4 text-muted-foreground" /></button>) : <p className="px-3 py-5 text-center text-sm text-muted-foreground">Aucun résultat pour cette recherche.</p>}</div>}
              {!searchQuery.trim() && <p className="px-2 py-4 text-xs leading-5 text-muted-foreground">Recherchez une expertise, une université, une ville ou un domaine d’études.</p>}
            </div>}
          </div>
          <div className="flex items-center gap-1 rounded-full border border-border bg-card px-2 py-1 text-xs font-semibold">
            <Languages className="size-3.5 text-muted-foreground" />
            <select aria-label="Choisir la langue" value={locale} onChange={event => setLocale(event.target.value as Locale)} className="bg-transparent text-[11px] outline-none">
              <option value="fr">FR</option><option value="en">EN</option><option value="zh">中文</option><option value="ro">RO</option><option value="pl">PL</option><option value="ar">عربي</option>
            </select>
          </div>
          <div className="flex items-center gap-1 rounded-full border border-border bg-card px-2 py-1 text-xs font-semibold"><Sun className="size-3.5 text-muted-foreground" /><select aria-label={copy.theme} value={theme} onChange={event => setTheme(event.target.value as "light" | "dark" | "system")} className="bg-transparent text-[11px] outline-none"><option value="light">{copy.light}</option><option value="dark">{copy.dark}</option><option value="system">{copy.system}</option></select></div>
          {isAuthenticated ? (
            <div className="ml-1 flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={() => setLocation("/mon-espace")}><LayoutDashboard />Mon espace</Button>
              <Button variant="ghost" size="icon" onClick={() => logout()} aria-label="Se déconnecter"><LogOut /></Button>
            </div>
          ) : (
            <>
              <Button variant="ghost" size="sm" onClick={() => setLocation("/connexion")}><LogIn />{copy.login}</Button>
              <Button size="sm" onClick={() => setLocation("/inscription")} className="rounded-full px-5">{copy.signup}<ArrowRight /></Button>
            </>
          )}
        </div>
        <button className="grid size-10 place-items-center rounded-full border border-border lg:hidden" onClick={() => setMenuOpen(prev => !prev)} aria-label="Ouvrir le menu">{menuOpen ? <X /> : <Menu />}</button>
      </div>
      {menuOpen && <div className="border-t border-border bg-background px-4 py-4 lg:hidden"><div className="container flex flex-col gap-1"><div className="mb-2 rounded-2xl border border-border bg-card p-3"><div className="flex items-center gap-2 rounded-xl border border-input bg-background px-3"><Search className="size-4 text-muted-foreground" /><input value={searchQuery} onChange={event => { setSearchQuery(event.target.value); setSearchOpen(true); }} placeholder="Rechercher..." className="h-11 min-w-0 flex-1 bg-transparent text-sm outline-none" /></div><div className="mt-2 flex gap-1"><button onClick={() => setSearchCategory("Tout")} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${searchCategory === "Tout" ? "bg-amber-600 text-white" : "bg-muted text-muted-foreground"}`}>Tout</button><button onClick={() => setSearchCategory("Services")} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${searchCategory === "Services" ? "bg-amber-600 text-white" : "bg-muted text-muted-foreground"}`}>Services</button><button onClick={() => setSearchCategory("Études")} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${searchCategory === "Études" ? "bg-amber-600 text-white" : "bg-muted text-muted-foreground"}`}>Études</button></div>{searchOpen && searchQuery.trim() && <div className="mt-2 border-t border-border pt-2">{searchResults.length ? searchResults.map(result => <button key={`${result.type}-${result.title}`} onClick={() => go(result.href)} className="flex w-full items-center gap-3 rounded-xl p-3 text-left hover:bg-muted"><span className="grid size-7 place-items-center rounded-lg bg-amber-50 text-amber-600 dark:bg-amber-500/10"><Search className="size-3.5" /></span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold">{result.title}</span><span className="block truncate text-xs text-muted-foreground">{result.detail}</span></span></button>) : <p className="px-2 py-3 text-xs text-muted-foreground">Aucun résultat.</p>}</div>}</div><div className="mb-2 flex items-center justify-between rounded-xl border border-border bg-card px-3 py-2"><span className="text-xs font-semibold text-muted-foreground">Thème</span><select aria-label="Choisir le thème" value={theme} onChange={event => setTheme(event.target.value as "light" | "dark" | "system")} className="bg-transparent text-xs font-semibold outline-none"><option value="light">Clair</option><option value="dark">Noir</option><option value="system">Système</option></select></div>{navItems.map(item => <button key={item.href} onClick={() => go(item.href)} className="rounded-lg px-3 py-3 text-left text-sm font-semibold hover:bg-muted">{item.label}</button>)}<div className="mt-2 flex gap-2 border-t border-border pt-3"><Button variant="outline" size="sm" onClick={() => setLocation("/connexion")} className="flex-1">{copy.login}</Button><Button size="sm" onClick={() => setLocation("/inscription")} className="flex-1">{copy.signup}</Button></div></div></div>}
    </header>
  );
}

