function ServiceWorkflow({ service, locale, need, step, setStep, onClose, setLocation }: { service: Service; locale: Locale; need: string; step: "detail" | "assessment" | "auth"; setStep: (step: "detail" | "assessment" | "auth") => void; onClose: () => void; setLocation: (path: string) => void }) {
  const Icon = service.icon;
  const meta = architectureCopy[service.architecture];
  const copy = translations[locale].ui;
  const { user } = useAuth();
  const save = trpc.workflow.save.useMutation();
  const submit = trpc.requests.create.useMutation({ onSuccess: () => { toast.success("Votre demande a été enregistrée dans votre espace."); onClose(); } });
  const [answer, setAnswer] = useState("");
  const [message, setMessage] = useState("");
  const [identity, setIdentity] = useState({ username: "", country: "" });
  const [attachments, setAttachments] = useState<{ fileName: string; mimeType: string; fileSize: number; data: string }[]>([]);
  const progressPercent = step === "detail" ? 33 : step === "assessment" ? 66 : 100;
  const readFile = (file: File) => new Promise<{ fileName: string; mimeType: string; fileSize: number; data: string }>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve({ fileName: file.name, mimeType: file.type || "application/octet-stream", fileSize: file.size, data: String(reader.result).split(",")[1] || "" });
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
  const handleAttachments = async (files: FileList | null) => {
    if (!files) return;
    const selected = Array.from(files).filter(file => file.size <= 8_000_000).slice(0, 5);
    if (selected.length < files.length) toast.error("5 fichiers maximum, 8 Mo par fichier.");
    try { setAttachments(await Promise.all(selected.map(readFile))); } catch { toast.error("Impossible de préparer un document."); }
  };
  const name = user?.name || "";
  const firstName = name.split(" ")[0] || "Client";
  const lastName = name.split(" ").slice(1).join(" ") || "ICX";
  useEffect(() => { if (user) save.mutate({ serviceKey: service.slug, need, step, answers: answer }); }, [step, answer, need, service.slug, user?.id]);
  return <div className="fixed inset-0 z-[80] grid place-items-center bg-[#17201c]/65 p-4 backdrop-blur-md" role="dialog" aria-modal="true" aria-label={`Parcours ${need}`}><div className="relative max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-[2rem] border border-border bg-card shadow-2xl"><button onClick={onClose} className="absolute right-5 top-5 z-10 grid size-9 place-items-center rounded-full border border-border bg-card text-muted-foreground transition hover:bg-muted" aria-label="Fermer"><X className="size-4" /></button><div className="border-b border-border bg-muted/50 p-7 pr-16"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-amber-100 text-amber-700 dark:bg-amber-400/15 dark:text-amber-200"><Icon className="size-5" /></span><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-amber-700 dark:text-amber-200">{meta.label}</p><h2 className="mt-1 text-xl font-semibold">{need}</h2></div></div><p className="mt-4 text-sm leading-6 text-muted-foreground">{meta.guidance}</p><div className="mt-6"><div className="mb-2 flex items-center justify-between text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground"><span>Progression du parcours</span><span>{progressPercent}%</span></div><div className="h-2 overflow-hidden rounded-full bg-border"><div className="h-full rounded-full bg-gradient-to-r from-amber-500 to-emerald-500 transition-all duration-300" style={{ width: `${progressPercent}%` }} /></div><div className="mt-2 flex justify-between text-[10px] text-muted-foreground"><span className={step === "detail" ? "font-bold text-amber-700" : ""}>Cadrage</span><span className={step === "assessment" ? "font-bold text-amber-700" : ""}>Évaluation</span><span className={step === "auth" ? "font-bold text-amber-700" : ""}>Demande</span></div></div></div>{step === "detail" && <div className="p-7"><p className="text-sm leading-6 text-muted-foreground">Choisissez le point d’entrée qui correspond à votre situation. Le parcours restera sauvegardé si vous êtes connecté.</p><div className="mt-6 grid gap-3">{meta.intents.map((option, index) => <button key={option} onClick={() => { setAnswer(option); setStep("assessment"); }} className="flex items-center gap-4 rounded-2xl border border-border bg-background p-4 text-left text-sm font-semibold transition hover:-translate-y-0.5 hover:border-amber-400 hover:shadow-lg"><span className="grid size-8 place-items-center rounded-full bg-amber-100 font-mono text-xs text-amber-700 dark:bg-amber-400/15 dark:text-amber-200">0{index + 1}</span><span className="flex-1">{option}</span><ChevronRight className="size-4 text-muted-foreground" /></button>)}</div></div>}{step === "assessment" && <div className="p-7"><p className="text-sm leading-6 text-muted-foreground">Cette étape aide ICX à adapter le niveau de détail, les documents et la prochaine action.</p><div className="mt-6 space-y-3">{meta.assessments.map((option, index) => <button key={option} onClick={() => { setAnswer(option); setStep("auth"); }} className="flex w-full items-center gap-4 rounded-2xl border border-border bg-background p-4 text-left transition hover:border-amber-400 hover:bg-amber-50/50 dark:hover:bg-amber-400/10"><span className="font-mono text-xs font-bold text-amber-700 dark:text-amber-200">0{index + 1}</span><span className="text-sm font-semibold">{option}</span><ChevronRight className="ml-auto size-4 text-muted-foreground" /></button>)}</div><button onClick={() => setStep("detail")} className="mt-6 text-xs font-semibold text-muted-foreground hover:text-foreground">← Revenir au choix</button></div>}{step === "auth" && <div className="p-7"><div className="grid size-12 place-items-center rounded-2xl bg-emerald-100 text-emerald-700 dark:bg-emerald-400/15 dark:text-emerald-200"><ShieldCheck className="size-6" /></div><h3 className="mt-5 text-2xl font-semibold">{user ? "Finaliser votre demande" : "Votre demande mérite un espace sécurisé."}</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">{user ? "Ajoutez le contexte utile : votre demande sera visible dans votre espace client et transmise à l’équipe ICX." : "Créez un compte ou connectez-vous pour enregistrer votre besoin, joindre des documents et retrouver votre progression."}</p>{user ? <form className="mt-6 space-y-4" onSubmit={event => { event.preventDefault(); submit.mutate({ serviceKey: service.slug, firstName, lastName, email: user.email || "client@icx.local", message: `${identity.username ? `[${copy.username}: ${identity.username}] ` : ""}${identity.country ? `[${copy.country}: ${identity.country}] ` : ""}${message || `${need} — ${answer}`}`, attachments }); }}><div className="grid gap-3 sm:grid-cols-2"><input required value={identity.username} onChange={event => setIdentity(current => ({ ...current, username: event.target.value }))} placeholder={copy.username} className="h-11 rounded-xl border border-input bg-background px-4 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /><input required value={identity.country} onChange={event => setIdentity(current => ({ ...current, country: event.target.value }))} placeholder={copy.country} className="h-11 rounded-xl border border-input bg-background px-4 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /></div><textarea required minLength={5} value={message} onChange={event => setMessage(event.target.value)} placeholder="Décrivez votre contexte, pays, calendrier et objectif..." className="min-h-28 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-amber-300 bg-amber-50/60 px-4 py-3 text-sm font-semibold text-amber-800 dark:border-amber-800 dark:bg-amber-500/10 dark:text-amber-200"><Paperclip className="size-4" /><span className="flex-1">Ajouter des documents <span className="block text-xs font-normal text-muted-foreground">PDF, image ou justificatif · 8 Mo maximum par fichier</span></span><input type="file" multiple onChange={event => void handleAttachments(event.target.files)} className="sr-only" /></label>{attachments.length > 0 && <div className="flex flex-wrap gap-2">{attachments.map(file => <span key={file.fileName} className="rounded-full bg-muted px-3 py-1.5 text-xs font-semibold">{file.fileName}</span>)}</div>}<Button disabled={submit.isPending} type="submit" className="h-11 w-full rounded-xl">{submit.isPending ? "Enregistrement..." : "Enregistrer la demande"}<ArrowRight /></Button></form> : <div className="mt-7 flex flex-col gap-3 sm:flex-row"><Button onClick={() => setLocation("/inscription")} className="rounded-full bg-amber-600 text-white hover:bg-amber-700">Créer mon espace<ArrowRight /></Button><Button onClick={() => setLocation("/connexion")} variant="outline" className="rounded-full">J’ai déjà un compte<LogIn /></Button></div>}<button onClick={() => setStep("assessment")} className="mt-6 text-xs font-semibold text-muted-foreground hover:text-foreground">← Modifier ma réponse</button></div>}</div></div>;
}

function ServicePage({ service, locale, setLocale, setLocation }: { service: Service; locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void }) {
  const view = serviceTranslations[locale][service.slug] ? { ...service, ...serviceTranslations[locale][service.slug] } : service;
  const [activeTab, setActiveTab] = useState(view.tabs[0]);
  const resumeKey = `icx-workflow-${service.slug}`;
  const [selectedNeed, setSelectedNeed] = useState<string | null>(() => localStorage.getItem(`${resumeKey}-need`));
  const [workflowStep, setWorkflowStep] = useState<"detail" | "assessment" | "auth">(() => (localStorage.getItem(`${resumeKey}-step`) as "detail" | "assessment" | "auth") || "detail");
  useEffect(() => { if (selectedNeed) localStorage.setItem(`${resumeKey}-need`, selectedNeed); else localStorage.removeItem(`${resumeKey}-need`); localStorage.setItem(`${resumeKey}-step`, workflowStep); }, [resumeKey, selectedNeed, workflowStep]);
  const Icon = service.icon;
  const dossiers = serviceDossiers[service.slug] || [];
  return <PageWrap><Header locale={locale} setLocale={setLocale} /><main><section className="relative overflow-hidden border-b border-border bg-[#1d2521] py-20 text-white md:py-28"><div className="absolute inset-0 hero-grid opacity-30" /><div className="container relative"><Link href="/" className="mb-12 inline-flex items-center gap-2 text-sm text-slate-400 hover:text-white"><ArrowRight className="size-4 rotate-180" />Retour à l’accueil</Link><div className="grid gap-12 lg:grid-cols-[1.1fr_.9fr] lg:items-end"><div><div className="mb-6 flex items-center gap-3 text-amber-300"><span className="grid size-12 place-items-center rounded-2xl bg-amber-400/10"><Icon /></span><span className="text-xs font-bold uppercase tracking-[0.2em]">{view.eyebrow}</span></div><h1 className="max-w-3xl text-5xl font-semibold leading-[1.04] tracking-[-0.055em] md:text-7xl">{view.label}</h1><p className="mt-7 max-w-2xl text-lg leading-8 text-slate-300">{view.description}</p></div><div className="rounded-3xl border border-white/10 bg-white/5 p-6 backdrop-blur"><p className="text-xs font-bold uppercase tracking-[0.18em] text-slate-400">Ce que vous pouvez attendre</p><div className="mt-5 flex flex-col gap-4">{view.outcomes.map(outcome => <div key={outcome} className="flex items-center gap-3 text-sm"><Check className="size-4 text-amber-300" />{outcome}</div>)}</div></div></div></div></section><section className="container py-10"><div className="flex gap-2 overflow-x-auto border-b border-border pb-px">{view.tabs.map(tab => <button key={tab} onClick={() => setActiveTab(tab)} className={`whitespace-nowrap border-b-2 px-4 py-3 text-sm font-semibold transition ${activeTab === tab ? "border-amber-600 text-amber-600" : "border-transparent text-muted-foreground hover:text-foreground"}`}>{tab}</button>)}</div><div className="mt-8 grid gap-4 md:grid-cols-3">{dossiers.map((dossier, index) => <Card key={dossier.label} className="rounded-2xl bg-card/80"><CardContent className="p-5"><div className="flex items-center justify-between"><span className="grid size-8 place-items-center rounded-lg bg-amber-100 font-mono text-xs font-bold text-amber-700 dark:bg-amber-400/15 dark:text-amber-200">0{index + 1}</span><ChevronRight className="size-4 text-muted-foreground" /></div><h3 className="mt-4 font-semibold">{dossier.label}</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">{dossier.description}</p><div className="mt-4 space-y-2">{dossier.items.map(item => <button key={item} onClick={() => { setSelectedNeed(item); setWorkflowStep("detail"); }} className="flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-xs font-semibold transition hover:bg-muted"><span className="size-1.5 rounded-full bg-amber-500" />{item}<ChevronRight className="ml-auto size-3 text-muted-foreground" /></button>)}</div></CardContent></Card>)}</div><div className="grid gap-12 py-14 lg:grid-cols-[1fr_.8fr]"><div><Eyebrow>{activeTab}</Eyebrow><h2 className="max-w-xl text-4xl font-semibold leading-tight tracking-[-0.045em]">Une progression structurée, adaptée à votre contexte.</h2><p className="mt-6 max-w-2xl text-lg leading-8 text-muted-foreground">{activeTab === view.tabs[0] ? view.description : `Sur le volet « ${activeTab} », notre équipe construit une réponse précise, documentée et actionnable. Le cadre est posé avec vous, puis suivi dans un espace sécurisé.`}</p><div className="mt-9 grid gap-3 sm:grid-cols-2">{service.subservices[view.tabs.indexOf(activeTab)]?.map((item, index) => <button key={item} onClick={() => { setSelectedNeed(item); setWorkflowStep("detail"); }} className="group flex items-center gap-3 rounded-xl border border-border bg-card p-4 text-left transition hover:-translate-y-0.5 hover:border-amber-300 hover:shadow-md"><span className="grid size-8 place-items-center rounded-lg bg-amber-50 font-mono text-xs font-bold text-amber-600 dark:bg-amber-500/10 dark:text-amber-300">0{index + 1}</span><span className="flex-1 text-sm font-semibold">{item}</span><ChevronRight className="size-4 text-muted-foreground transition group-hover:translate-x-1" /></button>)}</div></div><Card className="h-fit rounded-3xl border-amber-200 bg-amber-50/60 shadow-none dark:border-amber-900/50 dark:bg-amber-950/20"><CardHeader><div className="flex size-11 items-center justify-center rounded-xl bg-amber-500 text-white"><ClipboardList className="size-5" /></div><CardTitle className="pt-3 text-xl">Parlons de votre projet</CardTitle></CardHeader><CardContent><p className="text-sm leading-6 text-muted-foreground">Choisissez un sous-service pour commencer, puis ouvrez votre espace sécurisé afin de transmettre les informations utiles.</p><Button onClick={() => setLocation("/connexion")} className="mt-6 w-full rounded-full bg-amber-600 hover:bg-amber-700">Ouvrir un espace sécurisé<ArrowRight /></Button><p className="mt-4 flex items-center justify-center gap-2 text-center text-xs text-muted-foreground"><LockKeyhole className="size-3.5" />Données traitées avec confidentialité</p></CardContent></Card></div></section></main>{selectedNeed && <ServiceWorkflow service={service} locale={locale} need={selectedNeed} step={workflowStep} setStep={setWorkflowStep} onClose={() => setSelectedNeed(null)} setLocation={setLocation} />}<Footer setLocation={setLocation} /></PageWrap>;
}

function StudiesPage({ locale, setLocale, setLocation }: { locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void }) {
  const [country, setCountry] = useState("Tous les pays");
  const [level, setLevel] = useState("Tous les niveaux");
  const [query, setQuery] = useState("");
  const [catalogView, setCatalogView] = useState<"programmes" | "universites">("programmes");
  const [selected, setSelected] = useState<Program | null>(null);
  const filtered = useMemo(() => programs.filter(program => (country === "Tous les pays" || program.country === country) && (level === "Tous les niveaux" || program.level === level) && `${program.university} ${program.field} ${program.city}`.toLowerCase().includes(query.toLowerCase())), [country, level, query]);
  const universities = useMemo(() => Array.from(new Map(filtered.map(program => [program.university, program])).values()), [filtered]);
  return <PageWrap><Header locale={locale} setLocale={setLocale} /><main><section className="border-b border-border bg-[#f3f2ed] py-16 dark:bg-[#29332e]/40 md:py-24"><div className="container"><Eyebrow>Service Études</Eyebrow><div className="grid gap-10 lg:grid-cols-[1fr_.75fr] lg:items-end"><div><h1 className="max-w-3xl text-5xl font-semibold leading-[1.04] tracking-[-0.055em] md:text-7xl">Votre prochaine étape mérite un vrai point de départ.</h1><p className="mt-6 max-w-2xl text-lg leading-8 text-muted-foreground">Explorez les universités et programmes, comparez les critères et contactez ICX lorsque votre choix se précise.</p></div><div className="rounded-3xl border border-border bg-card p-6"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-2xl bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300"><GraduationCapIcon /></div><div><p className="text-sm font-semibold">Un espace pensé pour candidater</p><p className="mt-1 text-xs text-muted-foreground">Universités · programmes · suivi</p></div></div><div className="mt-5 grid grid-cols-3 gap-2 text-center"><div className="rounded-xl bg-muted p-3"><p className="text-xl font-semibold">07</p><p className="mt-1 text-[10px] uppercase tracking-wide text-muted-foreground">pays</p></div><div className="rounded-xl bg-muted p-3"><p className="text-xl font-semibold">{programs.length}</p><p className="mt-1 text-[10px] uppercase tracking-wide text-muted-foreground">programmes</p></div><div className="rounded-xl bg-muted p-3"><p className="text-xl font-semibold">1:1</p><p className="mt-1 text-[10px] uppercase tracking-wide text-muted-foreground">suivi</p></div></div></div></div></div></section><section className="container py-12 md:py-16"><div className="rounded-3xl border border-border bg-card p-4 shadow-sm md:p-6"><div className="flex flex-col gap-3 lg:flex-row lg:items-center"><div className="relative flex-1"><Search className="absolute left-4 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Rechercher une université, une ville ou un domaine" className="h-12 w-full rounded-xl border border-input bg-background pl-11 pr-4 text-sm outline-none ring-offset-background transition focus-visible:ring-2 focus-visible:ring-ring" /></div><div className="grid grid-cols-2 gap-3 lg:flex"><select value={catalogView} onChange={event => setCatalogView(event.target.value as "programmes" | "universites")} className="h-12 w-full min-w-[180px] rounded-xl border border-input bg-background px-3 text-sm font-semibold outline-none"><option value="universites">Universités</option><option value="programmes">Programmes d’études</option></select><div className="relative"><Globe2 className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><select value={country} onChange={event => setCountry(event.target.value)} className="h-12 w-full min-w-[160px] rounded-xl border border-input bg-background pl-9 pr-8 text-sm outline-none"><option value="Tous les pays">Pays</option>{countries.slice(1).map(item => <option key={item}>{item}</option>)}</select></div><select value={level} onChange={event => setLevel(event.target.value)} className="h-12 w-full min-w-[160px] rounded-xl border border-input bg-background px-3 text-sm outline-none"><option>Tous les niveaux</option><option>Bachelor</option><option>Master</option><option>Doctorat</option></select><Button variant="outline" size="icon" onClick={() => { setCountry("Tous les pays"); setLevel("Tous les niveaux"); setQuery(""); }} aria-label="Réinitialiser les filtres"><Filter /></Button></div></div></div><div className="mt-10 flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><p className="text-sm text-muted-foreground"><span className="font-semibold text-foreground">{catalogView === "programmes" ? filtered.length : universities.length}</span> {catalogView === "programmes" ? `programme${filtered.length > 1 ? "s" : ""}` : `université${universities.length > 1 ? "s" : ""}`} dans le catalogue</p></div><Button onClick={() => setLocation("/connexion")} className="w-fit rounded-full">Contacter ICX POWER SOLUTIONS SRL<ArrowRight /></Button></div><div className="mt-5 grid gap-4 lg:grid-cols-2">{catalogView === "programmes" ? filtered.map(program => <ProgramCard key={program.id} program={program} onClick={() => setSelected(program)} />) : universities.map(program => <UniversityCard key={program.university} program={program} onClick={() => setQuery(program.university)} />)}</div>{filtered.length === 0 && <div className="rounded-2xl border border-dashed border-border py-16 text-center"><Search className="mx-auto size-6 text-muted-foreground" /><p className="mt-4 font-semibold">Aucun résultat ne correspond à ces filtres.</p><p className="mt-1 text-sm text-muted-foreground">Essayez une autre combinaison ou contactez ICX pour une orientation personnalisée.</p></div>}</section></main>{selected && <ProgramDialog program={selected} onClose={() => setSelected(null)} onApply={() => { setSelected(null); setLocation("/connexion"); }} />}</PageWrap>;
}

function GraduationCapIcon() { return <span className="text-2xl">⌂</span>; }
function UniversityCard({ program, onClick }: { program: Program; onClick: () => void }) { return <button onClick={onClick} className="group rounded-2xl border border-border bg-card p-6 text-left transition hover:-translate-y-0.5 hover:border-amber-300 hover:shadow-lg"><div className="flex items-start justify-between gap-5"><div><Badge variant="secondary" className="rounded-full text-[10px]">{program.country}</Badge><h3 className="mt-4 text-xl font-semibold tracking-[-0.02em]">{program.university}</h3><p className="mt-2 text-sm text-muted-foreground">{program.city} · {program.level}</p></div><ChevronRight className="mt-1 size-5 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-amber-600" /></div><div className="mt-6 flex items-center justify-between border-t border-border pt-4"><span className="text-xs text-muted-foreground">Programmes disponibles</span><span className="text-sm font-semibold text-amber-600">Voir les options</span></div></button>; }
function ProgramCard({ program, onClick }: { program: Program; onClick: () => void }) { return <button onClick={onClick} className="group rounded-2xl border border-border bg-card p-5 text-left transition hover:-translate-y-0.5 hover:border-amber-300 hover:shadow-lg"><div className="flex items-start justify-between gap-5"><div><div className="flex flex-wrap gap-2"><Badge variant="secondary" className="rounded-full text-[10px]">{program.country}</Badge><Badge variant="outline" className="rounded-full text-[10px]">{program.level}</Badge></div><h3 className="mt-4 text-lg font-semibold tracking-[-0.02em]">{program.field}</h3><p className="mt-1 text-sm text-muted-foreground">{program.university} · {program.city}</p></div><ChevronRight className="mt-1 size-5 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-amber-600" /></div><div className="mt-6 grid grid-cols-2 gap-3 border-t border-border pt-4"><div><p className="text-[10px] font-bold uppercase tracking-[0.15em] text-muted-foreground">Rentrée</p><p className="mt-1 text-sm font-semibold">{program.intake}</p></div><div><p className="text-[10px] font-bold uppercase tracking-[0.15em] text-muted-foreground">Coût indicatif</p><p className="mt-1 truncate text-sm font-semibold">{program.cost}</p></div></div></button>; }
function ProgramDialog({ program, onClose, onApply }: { program: Program; onClose: () => void; onApply: () => void }) { return <div className="fixed inset-0 z-[80] flex items-end justify-center bg-[#1b2420]/55 p-0 backdrop-blur-sm md:items-center md:p-6" onClick={onClose}><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-t-3xl bg-card p-6 shadow-2xl md:rounded-3xl md:p-8" onClick={event => event.stopPropagation()}><div className="flex items-start justify-between gap-4"><div><div className="flex gap-2"><Badge variant="secondary" className="rounded-full">{program.country}</Badge><Badge variant="outline" className="rounded-full">{program.level}</Badge></div><h2 className="mt-4 text-3xl font-semibold tracking-[-0.04em]">{program.field}</h2><p className="mt-2 text-muted-foreground">{program.university} · {program.city}</p></div><button onClick={onClose} className="grid size-9 place-items-center rounded-full bg-muted text-muted-foreground" aria-label="Fermer"><X className="size-4" /></button></div><p className="mt-7 text-sm leading-7 text-muted-foreground">{program.description}</p><div className="mt-7 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-muted p-4"><Clock3 className="size-4 text-amber-600" /><p className="mt-3 text-[10px] font-bold uppercase tracking-[0.15em] text-muted-foreground">Calendrier</p><p className="mt-1 text-sm font-semibold">{program.intake}</p></div><div className="rounded-xl bg-muted p-4"><BarChart3 className="size-4 text-amber-600" /><p className="mt-3 text-[10px] font-bold uppercase tracking-[0.15em] text-muted-foreground">Budget</p><p className="mt-1 text-sm font-semibold">{program.cost}</p></div></div><div className="mt-7"><p className="text-sm font-semibold">Documents à prévoir</p><div className="mt-3 flex flex-wrap gap-2">{program.documents.map(document => <span key={document} className="flex items-center gap-2 rounded-full border border-border px-3 py-1.5 text-xs text-muted-foreground"><FileCheck2 className="size-3.5 text-emerald-600" />{document}</span>)}</div></div><div className="mt-8 flex flex-col-reverse gap-3 border-t border-border pt-6 sm:flex-row sm:justify-end"><Button variant="outline" onClick={onClose}>Fermer</Button><Button onClick={onApply}>Déposer ma demande<ArrowRight /></Button></div></div></div>; }

function AuthPage({ mode, locale, setLocale, setLocation }: { mode: "login" | "signup"; locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void }) { const [showPassword, setShowPassword] = useState(false); const isSignup = mode === "signup"; return <PageWrap><Header locale={locale} setLocale={setLocale} /><main className="relative grid min-h-[calc(100vh-74px)] place-items-center overflow-hidden bg-[#f3f2ed] py-12 dark:bg-[#1b2420]"><div className="absolute -left-20 top-10 size-80 rounded-full bg-amber-500/15 blur-[100px]" /><div className="absolute bottom-[-15%] right-[-5%] size-96 rounded-full bg-emerald-300/8 blur-[120px]" /><div className="relative grid w-full max-w-5xl gap-8 px-4 lg:grid-cols-[.9fr_1.1fr]"><div className="hidden rounded-3xl bg-[#1b2420] p-10 text-white lg:flex lg:flex-col lg:justify-between"><div><span className="grid size-12 place-items-center rounded-2xl bg-amber-600"><LockKeyhole /></span><h1 className="mt-10 text-4xl font-semibold leading-tight tracking-[-0.045em]">Votre espace pour avancer avec confiance.</h1><p className="mt-5 max-w-sm text-sm leading-6 text-slate-400">Retrouvez vos demandes, vos documents et le fil de chaque étape dans un même endroit.</p></div><div className="mt-16 space-y-4 text-sm text-slate-300"><p className="flex items-center gap-3"><Check className="size-4 text-amber-300" />Données protégées et accès sécurisé</p><p className="flex items-center gap-3"><Check className="size-4 text-amber-300" />Suivi clair des échanges</p><p className="flex items-center gap-3"><Check className="size-4 text-amber-300" />Notifications aux moments clés</p></div></div><Card className="rounded-3xl border-border bg-card p-2 shadow-xl"><CardHeader className="px-6 pb-4 pt-8 sm:px-10"><div className="flex items-center justify-between"><div><Eyebrow>{isSignup ? "Créer votre espace" : "Espace sécurisé"}</Eyebrow><CardTitle className="text-3xl tracking-[-0.045em]">{isSignup ? "Construisons la suite." : "Ravi de vous revoir."}</CardTitle><p className="mt-3 text-sm text-muted-foreground">{isSignup ? "Un compte pour centraliser votre projet." : "Connectez-vous pour retrouver vos dossiers."}</p></div><span className="grid size-11 place-items-center rounded-2xl bg-amber-50 text-amber-600 dark:bg-amber-500/10"><ShieldCheck /></span></div></CardHeader><CardContent className="px-6 pb-8 sm:px-10"><form onSubmit={event => { event.preventDefault(); toast.success(isSignup ? "Compte créé — vérifiez votre email pour confirmer." : "Connexion simulée — votre espace est prêt."); setLocation("/mon-espace"); }} className="space-y-4">{isSignup && <div className="grid gap-4 sm:grid-cols-2"><Field label="Prénom" placeholder="Votre prénom" /><Field label="Nom" placeholder="Votre nom" /></div>}<Field label="Email professionnel" placeholder="vous@exemple.com" type="email" />{isSignup && <div className="grid gap-4 sm:grid-cols-2"><Field label="Téléphone" placeholder="+40 ..." /><Field label="Pays" placeholder="Votre pays" /></div>}<div><label className="mb-2 block text-sm font-medium">Mot de passe</label><div className="relative"><input required minLength={10} type={showPassword ? "text" : "password"} placeholder="10 caractères minimum" className="h-11 w-full rounded-xl border border-input bg-background px-4 pr-12 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /><button type="button" onClick={() => setShowPassword(prev => !prev)} className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-semibold text-muted-foreground">{showPassword ? "Masquer" : "Afficher"}</button></div>{isSignup && <div className="mt-2 flex gap-1"><span className="h-1.5 flex-1 rounded-full bg-emerald-500" /><span className="h-1.5 flex-1 rounded-full bg-emerald-500" /><span className="h-1.5 flex-1 rounded-full bg-muted" /><span className="h-1.5 flex-1 rounded-full bg-muted" /></div>}</div>{isSignup && <label className="flex items-start gap-3 pt-1 text-xs leading-5 text-muted-foreground"><input type="checkbox" required className="mt-1 accent-blue-600" />J’accepte la politique de confidentialité et le traitement de mes données conformément au RGPD.</label>}{!isSignup && <div className="flex items-center justify-between text-xs"><label className="flex items-center gap-2 text-muted-foreground"><input type="checkbox" className="accent-blue-600" />Se souvenir de moi</label><button type="button" className="font-semibold text-amber-600">Mot de passe oublié ?</button></div>}<Button type="submit" className="h-12 w-full rounded-xl">{isSignup ? "Créer mon compte" : "Se connecter"}<ArrowRight /></Button></form><p className="mt-7 text-center text-sm text-muted-foreground">{isSignup ? "Vous avez déjà un compte ?" : "Pas encore de compte ?"} <button onClick={() => setLocation(isSignup ? "/connexion" : "/inscription")} className="font-semibold text-amber-600 hover:underline">{isSignup ? "Se connecter" : "Créer un compte"}</button></p></CardContent></Card></div></main></PageWrap>; }
function Field({ label, placeholder, type = "text", value, onChange }: { label: string; placeholder: string; type?: string; value?: string; onChange?: (value: string) => void }) { return <div><label className="mb-2 block text-sm font-medium">{label}</label><input required type={type} value={value} onChange={event => onChange?.(event.target.value)} placeholder={placeholder} className="h-11 w-full rounded-xl border border-input bg-background px-4 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /></div>; }

function WorkspacePage({ locale, setLocale, setLocation }: { locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void }) { const { user } = useAuth(); const requestsQuery = trpc.requests.mine.useQuery(undefined, { enabled: !!user }); const progressQuery = trpc.workflow.mine.useQuery(undefined, { enabled: !!user }); const documentsQuery = trpc.requests.documents.useQuery(undefined, { enabled: !!user }); const notificationsQuery = trpc.notifications.mine.useQuery(undefined, { enabled: !!user }); const requests = requestsQuery.data || []; const progress = progressQuery.data || []; const documents = documentsQuery.data || []; const notifications = notificationsQuery.data || []; if (!user) return <AuthGate locale={locale} setLocale={setLocale} setLocation={setLocation} title="Votre espace personnel" text="Connectez-vous pour déposer une demande, téléverser vos documents et suivre chaque étape." />; return <PageWrap><Header locale={locale} setLocale={setLocale} /><main className="bg-[#f3f2ed] py-10 dark:bg-[#1b2420]/50 md:py-14"><div className="container"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Eyebrow>Espace personnel</Eyebrow><h1 className="text-4xl font-semibold tracking-[-0.045em]">Bonjour {user.name?.split(" ")[0] || "et bienvenue"}.</h1><p className="mt-3 text-muted-foreground">Voici les dernières nouvelles de vos parcours.</p></div><Button onClick={() => setLocation("/etudes")} className="w-fit rounded-full">Explorer les programmes<ArrowRight /></Button></div><div className="mt-10 grid gap-4 md:grid-cols-3"><Metric icon={ClipboardList} label="Dossiers actifs" value="02" detail="+1 cette semaine" /><Metric icon={UploadCloud} label="Documents à fournir" value="04" detail="2 prioritaires" /><Metric icon={Clock3} label="Prochaine étape" value="48 h" detail="Vérification en cours" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.25fr_.75fr]"><Card className="rounded-2xl"><CardHeader><div className="flex items-center justify-between"><div><CardTitle>Mes dossiers</CardTitle><p className="mt-2 text-sm text-muted-foreground">Un aperçu de vos demandes en cours.</p></div><Button variant="ghost" size="sm">Voir tout<ArrowRight /></Button></div></CardHeader><CardContent className="space-y-3">{[["Master · Commerce international", "Université de Bordeaux", "En cours d’analyse", "68%"], ["Bachelor · International Economics", "Bucarest University of Economic Studies", "Documents complémentaires requis", "42%"]].map(item => <div key={item[0]} className="rounded-xl border border-border p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="font-semibold">{item[0]}</p><p className="mt-1 text-xs text-muted-foreground">{item[1]}</p></div><Badge className="w-fit rounded-full bg-amber-100 text-amber-800 hover:bg-amber-100 dark:bg-amber-500/15 dark:text-amber-300">{item[2]}</Badge></div><div className="mt-4 flex items-center gap-3"><div className="h-2 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-amber-600" style={{ width: item[3] }} /></div><span className="text-xs font-semibold text-muted-foreground">{item[3]}</span></div></div>)}</CardContent></Card><Card className="rounded-2xl"><CardHeader><CardTitle>Prochaines actions</CardTitle></CardHeader><CardContent className="space-y-4">{["Ajouter votre relevé de notes", "Valider la lettre de motivation", "Répondre à votre conseiller"].map((action, index) => <button key={action} className="flex w-full items-center gap-3 text-left"><span className={`grid size-8 place-items-center rounded-full ${index === 0 ? "bg-amber-600 text-white" : "bg-muted text-muted-foreground"}`}>{index === 0 ? <UploadCloud className="size-4" /> : <span className="text-xs font-semibold">0{index + 1}</span>}</span><span className="flex-1 text-sm font-medium">{action}</span><ChevronRight className="size-4 text-muted-foreground" /></button>)}</CardContent></Card><Card className="mt-6 rounded-2xl lg:col-span-2"><CardHeader><CardTitle>Parcours sauvegardés</CardTitle><p className="mt-2 text-sm text-muted-foreground">Reprenez un besoin là où vous l’avez laissé, ou consultez les demandes déjà transmises à ICX.</p></CardHeader><CardContent className="grid gap-3 md:grid-cols-2">{progress.length === 0 && requests.length === 0 ? <p className="text-sm text-muted-foreground">Aucun parcours enregistré pour le moment. Commencez par choisir un service.</p> : <>{progress.map(item => <button key={`progress-${item.id}`} onClick={() => setLocation(`/services/${item.serviceKey}`)} className="rounded-xl border border-border p-4 text-left transition hover:border-amber-300 hover:bg-muted"><p className="font-semibold">{item.need}</p><p className="mt-1 text-xs text-muted-foreground">{item.serviceKey} · étape {item.step}</p><span className="mt-3 inline-flex text-xs font-semibold text-amber-700">Reprendre le parcours <ArrowRight className="ml-1 size-3" /></span></button>)}{requests.map(item => <div key={`request-${item.id}`} className="rounded-xl border border-border p-4"><p className="font-semibold">Demande · {item.serviceKey}</p><p className="mt-1 line-clamp-2 text-xs text-muted-foreground">{item.message}</p><Badge className="mt-3 rounded-full bg-amber-100 text-amber-800 hover:bg-amber-100">{item.status}</Badge></div>)}</>}</CardContent></Card><Card className="mt-6 rounded-2xl lg:col-span-2"><CardHeader><CardTitle>Notifications</CardTitle><p className="mt-2 text-sm text-muted-foreground">Les demandes reçues et les changements de statut apparaissent automatiquement ici.</p></CardHeader><CardContent>{notifications.length === 0 ? <p className="text-sm text-muted-foreground">Aucune notification pour le moment.</p> : <div className="space-y-3">{notifications.slice(0, 5).map(notification => <div key={notification.id} className="flex items-start gap-3 rounded-xl border border-border p-4"><span className="mt-0.5 grid size-8 place-items-center rounded-full bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-200"><Bell className="size-4" /></span><div><p className="text-sm font-semibold">{notification.title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{notification.content}</p><p className="mt-2 text-[10px] uppercase tracking-[0.14em] text-muted-foreground">{new Date(notification.createdAt).toLocaleString()}</p></div></div>)}</div>}</CardContent></Card><Card className="mt-6 rounded-2xl lg:col-span-2"><CardHeader><CardTitle>Documents transmis</CardTitle><p className="mt-2 text-sm text-muted-foreground">Les pièces jointes à vos demandes sont conservées dans votre espace sécurisé.</p></CardHeader><CardContent>{documents.length === 0 ? <p className="text-sm text-muted-foreground">Aucun document transmis pour le moment.</p> : <div className="grid gap-3 sm:grid-cols-2">{documents.map(document => <a key={document.id} href={document.fileUrl} target="_blank" rel="noreferrer" className="flex items-center gap-3 rounded-xl border border-border p-4 transition hover:border-amber-300 hover:bg-muted"><span className="grid size-9 place-items-center rounded-lg bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-200"><Paperclip className="size-4" /></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{document.fileName}</span><span className="mt-1 block text-xs text-muted-foreground">{Math.round(document.fileSize / 1024)} Ko · Ouvrir</span></span><ArrowRight className="size-4 text-muted-foreground" /></a>)}</div>}</CardContent></Card></div></div></main></PageWrap>; }
function Metric({ icon: Icon, label, value, detail }: { icon: React.ElementType; label: string; value: string; detail: string }) { return <Card className="rounded-2xl"><CardContent className="flex items-start justify-between p-5"><div><p className="text-xs font-semibold text-muted-foreground">{label}</p><p className="mt-3 text-3xl font-semibold tracking-[-0.05em]">{value}</p><p className="mt-1 text-xs text-emerald-600">{detail}</p></div><span className="grid size-10 place-items-center rounded-xl bg-amber-50 text-amber-600 dark:bg-amber-500/10"><Icon className="size-5" /></span></CardContent></Card>; }

function AdminPage({ locale, setLocale, setLocation }: { locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void }) {
  const { user } = useAuth();
  const [panel, setPanel] = useState("dashboard");
  if (!user) return <AuthGate locale={locale} setLocale={setLocale} setLocation={setLocation} title="Console opérations" text="L’interface d’administration est réservée aux comptes habilités." admin />;
  const nav = [{ key: "dashboard", label: "Tableau de bord", icon: LayoutDashboard }, { key: "requests", label: "Demandes & dossiers", icon: ClipboardList }, { key: "users", label: "Utilisateurs", icon: Users }, { key: "content", label: "Universités & contenu", icon: GraduationCapIcon }, { key: "audit", label: "Journal d’audit", icon: ShieldCheck }];
  const titles: Record<string, string> = { dashboard: "Vue d’ensemble des demandes.", requests: "Demandes & dossiers.", users: "Utilisateurs de la plateforme.", content: "Universités et contenu.", audit: "Traçabilité des actions." };
  return <div className="dark min-h-screen bg-[#111816] text-slate-100"><header className="border-b border-white/10 bg-[#0d1210] px-5 py-4"><div className="mx-auto flex max-w-[1440px] items-center justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[0.2em] text-amber-300">ICX POWER SOLUTIONS</p><h1 className="mt-1 text-lg font-semibold">ICX Operations</h1><p className="text-xs text-slate-400">Console interne · accès restreint</p></div><button onClick={() => setLocation("/")} className="rounded-full border border-white/15 px-4 py-2 text-xs font-semibold text-slate-300 transition hover:border-amber-300 hover:text-white">← Retour au portail</button></div></header><main className="min-h-[calc(100vh-82px)] bg-[#111816]"><div className="container grid gap-6 py-6 md:py-8 lg:grid-cols-[220px_1fr]"><aside className="h-fit rounded-2xl border border-border bg-card p-3 lg:sticky lg:top-24"><div className="flex items-center gap-3 border-b border-border px-3 pb-4"><span className="grid size-9 place-items-center rounded-xl bg-[#1b2420] text-amber-300"><Settings2 className="size-4" /></span><div><p className="text-sm font-bold">ICX Operations</p><p className="text-[10px] uppercase tracking-[0.16em] text-muted-foreground">Admin console</p></div></div><nav className="mt-3 space-y-1" aria-label="Navigation administration">{nav.map(item => { const Icon = item.icon; return <button key={item.key} onClick={() => setPanel(item.key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition ${panel === item.key ? "bg-amber-600 text-white shadow-md shadow-amber-600/20" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}><Icon className="size-4" />{item.label}</button>; })}</nav><div className="mt-6 rounded-xl bg-muted p-3"><div className="flex items-center gap-2 text-xs font-semibold"><span className="size-2 rounded-full bg-emerald-500" />Système opérationnel</div><p className="mt-2 text-[11px] leading-5 text-muted-foreground">Notifications, stockage signé et historique prêts à connecter.</p></div></aside><section className="min-w-0"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Eyebrow>Console opérations</Eyebrow><h1 className="text-4xl font-semibold tracking-[-0.045em]">{titles[panel]}</h1><p className="mt-3 text-muted-foreground">Pilotez les dossiers, les utilisateurs et les contenus depuis un même espace.</p></div><Button variant="outline" onClick={() => toast.success("Export préparé — fonctionnalité prête à brancher")}>Exporter le rapport</Button></div>{panel === "dashboard" && <><div className="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><AdminMetric label="Dossiers entrants" value="24" delta="+18%" icon={InboxIcon} /><AdminMetric label="En cours d’analyse" value="11" delta="5 prioritaires" icon={Search} /><AdminMetric label="Documents reçus" value="48" delta="Cette semaine" icon={FileCheck2} /><AdminMetric label="Taux de réponse" value="94%" delta="+6 pts" icon={BarChart3} /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.35fr_.65fr]"><RequestTable /><QuickActions /></div></>}{panel === "requests" && <div className="mt-6 grid gap-6"><RequestTable detailed /><Card className="rounded-2xl"><CardHeader><CardTitle>Statuts de traitement</CardTitle></CardHeader><CardContent><div className="grid gap-3 md:grid-cols-5">{[["Reçu", "08", "bg-emerald-100 text-emerald-800"], ["En analyse", "11", "bg-amber-100 text-amber-800"], ["Compléments", "03", "bg-amber-100 text-blue-800"], ["Accepté", "06", "bg-violet-100 text-violet-800"], ["Clôturé", "18", "bg-slate-100 text-slate-700"]].map(([label, value, color]) => <div key={label} className="rounded-xl border border-border p-4"><span className={`inline-flex rounded-full px-2 py-1 text-[10px] font-bold ${color}`}>{label}</span><p className="mt-3 text-2xl font-semibold">{value}</p><p className="mt-1 text-xs text-muted-foreground">dossiers</p></div>)}</div></CardContent></Card></div>}{panel === "users" && <Card className="mt-8 rounded-2xl"><CardHeader><CardTitle>Comptes récents</CardTitle><p className="mt-2 text-sm text-muted-foreground">Activation, rôle et accès 2FA à piloter depuis cette liste.</p></CardHeader><CardContent><div className="space-y-3">{[["Aïcha Camara", "aicha@example.com", "Client", "Actif"], ["Mamadou Bah", "mamadou@example.com", "Client", "Actif"], ["Sofia Nistor", "sofia@example.com", "Admin en attente", "À vérifier"]].map(userRow => <div key={userRow[1]} className="flex flex-col gap-3 rounded-xl border border-border p-4 sm:flex-row sm:items-center"><span className="grid size-10 place-items-center rounded-full bg-amber-100 text-sm font-bold text-amber-700">{userRow[0].split(" ").map(part => part[0]).join("")}</span><div className="flex-1"><p className="text-sm font-semibold">{userRow[0]}</p><p className="mt-1 text-xs text-muted-foreground">{userRow[1]}</p></div><span className="text-xs text-muted-foreground">{userRow[2]}</span><Badge variant={userRow[3] === "Actif" ? "secondary" : "outline"} className="w-fit rounded-full">{userRow[3]}</Badge><Button variant="ghost" size="icon" onClick={() => toast.info("Gestion utilisateur prête à connecter")}><ChevronRight /></Button></div>)}</div></CardContent></Card>}{panel === "content" && <div className="mt-8 grid gap-4 md:grid-cols-2"><Card className="rounded-2xl"><CardContent className="p-6"><GraduationCapIcon /><h2 className="mt-5 text-xl font-semibold">Catalogue Études</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Créer, modifier et archiver universités, programmes, calendriers et documents requis.</p><Button className="mt-6" onClick={() => toast.info("CRUD universités/programmes prêt à connecter")}>Gérer le catalogue<ArrowRight /></Button></CardContent></Card><Card className="rounded-2xl"><CardContent className="p-6"><Handshake className="size-6 text-amber-600" /><h2 className="mt-5 text-xl font-semibold">Partenaires</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Mettre à jour les logos, descriptions et informations légales des partenaires.</p><Button variant="outline" className="mt-6" onClick={() => setLocation("/partenaires")}>Voir les partenaires<ArrowRight /></Button></CardContent></Card></div>}{panel === "audit" && <Card className="mt-8 rounded-2xl"><CardHeader><CardTitle>Journal des actions sensibles</CardTitle><p className="mt-2 text-sm text-muted-foreground">Historique préparé pour les changements de statut, de rôle et de contenu.</p></CardHeader><CardContent><div className="space-y-4">{[["Statut dossier #ICX-024 changé", "En cours d’analyse → Documents complémentaires requis", "Il y a 12 min"], ["Programme mis à jour", "Université de Bordeaux · Master Commerce international", "Il y a 1 h"], ["Rôle utilisateur modifié", "Sofia Nistor · Admin en attente", "Hier"]].map(log => <div key={log[0]} className="flex gap-4 border-b border-border pb-4 last:border-0 last:pb-0"><span className="mt-1 size-2 rounded-full bg-amber-600" /><div className="flex-1"><p className="text-sm font-semibold">{log[0]}</p><p className="mt-1 text-xs text-muted-foreground">{log[1]}</p></div><span className="text-xs text-muted-foreground">{log[2]}</span></div>)}</div></CardContent></Card>}</section></div></main></div>;
}

function RequestTable({ detailed = false }: { detailed?: boolean }) { return <Card className="rounded-2xl"><CardHeader><div className="flex items-center justify-between"><div><CardTitle>Demandes récentes</CardTitle><p className="mt-2 text-sm text-muted-foreground">{detailed ? "Toutes les soumissions, filtrables par service et statut." : "Les dernières activités de la plateforme."}</p></div><Button variant="ghost" size="sm">Filtrer<Filter /></Button></div></CardHeader><CardContent><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-border text-[10px] uppercase tracking-[0.15em] text-muted-foreground"><tr><th className="pb-3 font-semibold">Demande</th><th className="pb-3 font-semibold">Service</th><th className="pb-3 font-semibold">Statut</th><th className="pb-3 font-semibold">Date</th></tr></thead><tbody className="divide-y divide-border"><tr><td className="py-4"><p className="font-semibold">Aïcha Camara</p><p className="mt-1 text-xs text-muted-foreground">Master · Bordeaux</p></td><td className="py-4 text-muted-foreground">Études</td><td className="py-4"><Badge className="rounded-full bg-amber-100 text-amber-800 hover:bg-amber-100 dark:bg-amber-500/15 dark:text-amber-300">En cours</Badge></td><td className="py-4 text-muted-foreground">Aujourd’hui</td></tr><tr><td className="py-4"><p className="font-semibold">Mamadou Bah</p><p className="mt-1 text-xs text-muted-foreground">Sourcing fournisseurs</p></td><td className="py-4 text-muted-foreground">Sourcing</td><td className="py-4"><Badge className="rounded-full bg-emerald-100 text-emerald-800 hover:bg-emerald-100 dark:bg-emerald-500/15 dark:text-emerald-300">Reçu</Badge></td><td className="py-4 text-muted-foreground">Hier</td></tr><tr><td className="py-4"><p className="font-semibold">Sofia Nistor</p><p className="mt-1 text-xs text-muted-foreground">Structuration d’entreprise</p></td><td className="py-4 text-muted-foreground">Business</td><td className="py-4"><Badge variant="secondary" className="rounded-full">À assigner</Badge></td><td className="py-4 text-muted-foreground">24 sept.</td></tr></tbody></table></div></CardContent></Card>; }

function QuickActions() { return <Card className="rounded-2xl"><CardHeader><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-amber-50 text-amber-600 dark:bg-amber-500/10"><Settings2 className="size-5" /></div><div><CardTitle>Raccourcis</CardTitle><p className="mt-1 text-sm text-muted-foreground">Actions fréquentes</p></div></div></CardHeader><CardContent className="space-y-3">{[["Revoir les dossiers à risque", "5 dossiers", Search], ["Mettre à jour le catalogue", "7 programmes", GraduationCapIcon], ["Voir le journal d’audit", "Aujourd’hui", ShieldCheck]].map(([label, detail, Icon]) => <button key={label as string} className="flex w-full items-center gap-3 rounded-xl border border-border p-3 text-left transition hover:border-amber-300 hover:bg-muted"><span className="grid size-9 place-items-center rounded-lg bg-muted text-muted-foreground">{typeof Icon === "function" ? <Icon /> : null}</span><span className="flex-1"><span className="block text-sm font-semibold">{label as string}</span><span className="mt-1 block text-xs text-muted-foreground">{detail as string}</span></span><ChevronRight className="size-4 text-muted-foreground" /></button>)}</CardContent></Card>; }

function InboxIcon() { return <span className="text-lg">↘</span>; }
function AdminMetric({ label, value, delta, icon: Icon }: { label: string; value: string; delta: string; icon: React.ElementType }) { return <Card className="rounded-2xl"><CardContent className="p-5"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-muted-foreground">{label}</p><Icon className="size-4 text-amber-600" /></div><p className="mt-4 text-3xl font-semibold tracking-[-0.05em]">{value}</p><p className="mt-1 text-xs text-emerald-600">{delta}</p></CardContent></Card>; }

function AuthGate({ locale, setLocale, setLocation, title, text, admin = false }: { locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void; title: string; text: string; admin?: boolean }) { return <PageWrap><Header locale={locale} setLocale={setLocale} /><main className="grid min-h-[calc(100vh-74px)] place-items-center bg-[#f3f2ed] px-4 py-16 dark:bg-[#1b2420]"><Card className="w-full max-w-lg rounded-3xl p-2 text-center shadow-xl"><CardContent className="px-6 py-12 sm:px-12"><span className={`mx-auto grid size-16 place-items-center rounded-3xl ${admin ? "bg-slate-900 text-amber-300" : "bg-amber-50 text-amber-600 dark:bg-amber-500/10"}`}>{admin ? <Settings2 /> : <LockKeyhole />}</span><h1 className="mt-7 text-3xl font-semibold tracking-[-0.045em]">{title}</h1><p className="mx-auto mt-4 max-w-sm text-sm leading-6 text-muted-foreground">{text}</p><Button onClick={() => setLocation("/connexion")} className="mt-8 rounded-full px-6">Se connecter<ArrowRight /></Button><p className="mt-4 text-xs text-muted-foreground">Pas encore de compte ? <button onClick={() => setLocation("/inscription")} className="font-semibold text-amber-600">Créer un compte</button></p></CardContent></Card></main></PageWrap>; }

function PartnershipDialog({ onClose, setLocation }: { onClose: () => void; setLocation: (path: string) => void }) {
  const { user } = useAuth();
  const mutation = trpc.partnerships.create.useMutation({ onSuccess: () => { toast.success("Votre demande de partenariat a été enregistrée."); onClose(); } });
  const [form, setForm] = useState({ companyName: "", contactName: "", email: user?.email || "", phone: "", needs: "" });
  if (!user) return <div className="fixed inset-0 z-[90] grid place-items-center bg-[#17201c]/65 p-4 backdrop-blur-md"><Card className="w-full max-w-md rounded-3xl p-2"><CardContent className="p-7 text-center"><Handshake className="mx-auto size-10 text-amber-600" /><h2 className="mt-5 text-2xl font-semibold">Un espace entreprise sécurisé</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Connectez-vous pour déposer une proposition de partenariat et suivre sa qualification.</p><div className="mt-7 flex gap-3"><Button variant="outline" onClick={onClose} className="flex-1">Fermer</Button><Button onClick={() => setLocation("/connexion")} className="flex-1">Se connecter<ArrowRight /></Button></div></CardContent></Card></div>;
  return <div className="fixed inset-0 z-[90] grid place-items-center bg-[#17201c]/65 p-4 backdrop-blur-md" role="dialog" aria-modal="true"><Card className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-3xl p-2"><CardHeader className="flex flex-row items-start justify-between gap-4 px-6 pt-7"><div><Eyebrow>Partenariat entreprise</Eyebrow><CardTitle className="text-3xl tracking-[-0.04em]">Construisons une coopération utile.</CardTitle><p className="mt-3 text-sm leading-6 text-muted-foreground">Présentez votre structure, vos marchés et le type de collaboration recherché.</p></div><button onClick={onClose} className="grid size-9 place-items-center rounded-full bg-muted" aria-label="Fermer"><X className="size-4" /></button></CardHeader><CardContent className="px-6 pb-7"><form className="space-y-4" onSubmit={event => { event.preventDefault(); mutation.mutate(form); }}><div className="grid gap-4 sm:grid-cols-2"><Field label="Raison sociale" placeholder="Nom de l’entreprise" value={form.companyName} onChange={value => setForm(prev => ({ ...prev, companyName: value }))} /><Field label="Interlocuteur" placeholder="Nom complet" value={form.contactName} onChange={value => setForm(prev => ({ ...prev, contactName: value }))} /></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Email professionnel" type="email" placeholder="vous@entreprise.com" value={form.email} onChange={value => setForm(prev => ({ ...prev, email: value }))} /><Field label="Téléphone" placeholder="+40 ..." value={form.phone} onChange={value => setForm(prev => ({ ...prev, phone: value }))} /></div><div><label className="mb-2 block text-sm font-medium">Besoin de coopération</label><textarea required minLength={10} value={form.needs} onChange={event => setForm(prev => ({ ...prev, needs: event.target.value }))} placeholder="Pays concernés, objectif, expertise recherchée, calendrier..." className="min-h-32 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /></div><Button disabled={mutation.isPending} type="submit" className="h-12 w-full rounded-xl">{mutation.isPending ? "Enregistrement..." : "Envoyer la proposition"}<ArrowRight /></Button></form></CardContent></Card></div>;
}

function InfoPage({ kind, locale, setLocale, setLocation }: { kind: "partners" | "privacy" | "legal"; locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void }) {
  const [partnershipOpen, setPartnershipOpen] = useState(false);
  const content = kind === "partners" ? { eyebrow: "Écosystème", title: "Des partenaires qui partagent le même sens du suivi.", body: "ICX construit des passerelles avec des organisations complémentaires, dans le respect des rôles et des engagements de chacun." } : kind === "privacy" ? { eyebrow: "Confidentialité", title: "Vos données méritent un cadre clair.", body: "Cette page présente l’intention de la politique de confidentialité. Les mentions définitives, les durées de conservation et les coordonnées du responsable de traitement devront être validées avant mise en production." } : { eyebrow: "Mentions légales", title: "Les informations légales d’ICX, en clair.", body: "Les informations ci-dessous correspondent aux données publiques consultées dans les bases roumaines d’entreprises et doivent rester alignées sur les documents officiels de la société." };
  return <PageWrap><Header locale={locale} setLocale={setLocale} /><main className="container py-20 md:py-28"><Eyebrow>{content.eyebrow}</Eyebrow><h1 className="max-w-3xl text-5xl font-semibold leading-[1.04] tracking-[-0.055em] md:text-7xl">{content.title}</h1><p className="mt-7 max-w-2xl text-lg leading-8 text-muted-foreground">{content.body}</p>{kind === "partners" ? <><div className="mt-9 flex flex-wrap gap-3"><Button onClick={() => setPartnershipOpen(true)} className="rounded-full">Proposer un partenariat entreprise<Handshake /></Button><Button variant="outline" onClick={() => setLocation("/#services")} className="rounded-full">Découvrir nos expertises<ArrowRight /></Button></div><div className="mt-12 grid gap-4 md:grid-cols-2"><Card className="rounded-2xl"><CardContent className="p-7"><div className="flex size-12 items-center justify-center overflow-hidden rounded-2xl bg-white ring-1 ring-border"><img src="/assets/lorondo-logo.jpg" alt="Logo Lorondo Services SRL" className="size-full object-contain p-1" /></div><h2 className="mt-6 text-xl font-semibold">Lorondo Services SRL</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Partenaire opérationnel en Roumanie, avec une identité visuelle désormais affichée dans l’écosystème ICX.</p></CardContent></Card><Card className="rounded-2xl"><CardContent className="p-7"><div className="flex size-12 items-center justify-center overflow-hidden rounded-2xl bg-white ring-1 ring-border"><img src="/assets/aaft-official.jpg" alt="Logo officiel AAFT" className="size-full object-cover" /></div><h2 className="mt-6 text-xl font-semibold">AAFT Association</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Partenaire associatif en Roumanie. Logo public récupéré depuis la page officielle et identité à confirmer avec le partenaire.</p></CardContent></Card></div></> : <Card className="mt-12 max-w-3xl rounded-2xl"><CardContent className="space-y-5 p-7 text-sm leading-7 text-muted-foreground"><p>ICX POWER SOLUTIONS SRL · Roumanie</p><p className="rounded-xl border border-dashed border-amber-300 bg-amber-50 p-4 text-amber-900 dark:border-amber-700 dark:bg-amber-950/30 dark:text-amber-200">CUI 54675848 · Nr. Reg. Com. J2026031336000 · siège : Str. Hlincea 47, Iași, 700715, Roumanie · CAEN 7020 · créée le 13 mai 2026.</p><p>Les contenus de cette interface sont fournis à titre informatif et ne remplacent pas la validation contractuelle des documents légaux.</p></CardContent></Card>}<Button variant="outline" onClick={() => setLocation("/")} className="mt-10 rounded-full">Retour à l’accueil<ArrowRight className="rotate-180" /></Button></main>{partnershipOpen && <PartnershipDialog onClose={() => setPartnershipOpen(false)} setLocation={setLocation} />}<Footer setLocation={setLocation} /></PageWrap>;
}

function AuthPageV2({ mode, locale, setLocale, setLocation }: { mode: "login" | "signup"; locale: Locale; setLocale: (locale: Locale) => void; setLocation: (path: string) => void }) {
  const copy = translations[locale].ui;
  const isSignup = mode === "signup";
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ username: "", country: "", phone: "", password: "", confirmation: "", privacy: false, twoFactor: true });
  const update = (key: keyof typeof form, value: string | boolean) => setForm(current => ({ ...current, [key]: value }));
  const handleSubmit = (event: React.FormEvent) => { event.preventDefault(); if (isSignup && form.password !== form.confirmation) { toast.error("Les mots de passe ne correspondent pas."); return; } toast.success(isSignup ? "Compte créé — vérifiez votre email pour confirmer." : "Connexion simulée — votre espace est prêt."); setLocation("/mon-espace"); };
  return <PageWrap><Header locale={locale} setLocale={setLocale} /><main className="relative grid min-h-[calc(100vh-74px)] place-items-center overflow-hidden bg-[#f3f2ed] py-8 dark:bg-[#1b2420]"><div className="relative grid w-full max-w-4xl gap-6 px-4 lg:grid-cols-[.8fr_1.2fr]"><div className="hidden rounded-3xl bg-[#1b2420] p-8 text-white lg:flex lg:flex-col lg:justify-between"><div><span className="grid size-11 place-items-center rounded-2xl bg-amber-600"><LockKeyhole /></span><h1 className="mt-7 text-3xl font-semibold leading-tight">Votre espace pour avancer avec confiance.</h1><p className="mt-4 text-sm leading-6 text-slate-400">Retrouvez vos demandes, vos documents et le fil de chaque étape dans un même endroit.</p></div><div className="space-y-3 text-sm text-slate-300"><p className="flex items-center gap-3"><Check className="size-4 text-amber-300" />Données protégées et accès sécurisé</p><p className="flex items-center gap-3"><Check className="size-4 text-amber-300" />Suivi clair des échanges</p></div></div><Card className="rounded-3xl border-border bg-card p-2 shadow-xl"><CardHeader className="px-5 pb-3 pt-6 sm:px-8"><div className="flex items-center justify-between"><div><Eyebrow>{isSignup ? copy.signup : copy.secureSpace}</Eyebrow><CardTitle className="text-2xl tracking-[-0.04em]">{isSignup ? "Construisons la suite." : "Ravi de vous revoir."}</CardTitle><p className="mt-2 text-sm text-muted-foreground">{isSignup ? "Un compte pour centraliser votre projet." : "Connectez-vous pour retrouver vos dossiers."}</p></div><span className="grid size-10 place-items-center rounded-2xl bg-amber-50 text-amber-600 dark:bg-amber-500/10"><ShieldCheck /></span></div></CardHeader><CardContent className="px-5 pb-6 sm:px-8"><form onSubmit={handleSubmit} className="space-y-3">{isSignup && <div className="grid gap-3 sm:grid-cols-2"><Field label={copy.username} placeholder={copy.usernameHint} value={form.username} onChange={value => update("username", value)} /><Field label={copy.country} placeholder="Roumanie, France, Canada…" value={form.country} onChange={value => update("country", value)} /></div>}{isSignup && <Field label={copy.phone} placeholder="+40 000 000 000" value={form.phone} onChange={value => update("phone", value)} />}<div><label className="mb-1.5 block text-sm font-medium">{copy.password}</label><div className="relative"><input required minLength={10} value={form.password} onChange={event => update("password", event.target.value)} type={showPassword ? "text" : "password"} placeholder="10 caractères minimum" className="h-11 w-full rounded-xl border border-input bg-background px-4 pr-20 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /><button type="button" onClick={() => setShowPassword(prev => !prev)} className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-semibold text-muted-foreground">{showPassword ? copy.hide : copy.show}</button></div></div>{isSignup && <><div><label className="mb-1.5 block text-sm font-medium">{copy.confirmPassword}</label><input required minLength={10} value={form.confirmation} onChange={event => update("confirmation", event.target.value)} type="password" placeholder={copy.confirmPassword} className="h-11 w-full rounded-xl border border-input bg-background px-4 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring" /></div><label className="flex items-start gap-2 pt-1 text-xs leading-5 text-muted-foreground"><input type="checkbox" required checked={form.privacy} onChange={event => update("privacy", event.target.checked)} className="mt-1 accent-amber-600" />{copy.privacyConsent}</label><label className="flex items-start gap-2 text-xs leading-5 text-muted-foreground"><input type="checkbox" checked={form.twoFactor} onChange={event => update("twoFactor", event.target.checked)} className="mt-1 accent-amber-600" />{copy.twoFactor}</label></>}{!isSignup && <div className="flex items-center justify-between text-xs"><label className="flex items-center gap-2 text-muted-foreground"><input type="checkbox" className="accent-amber-600" />{copy.remember}</label><button type="button" className="font-semibold text-amber-600">{copy.forgot}</button></div>}<Button type="submit" className="h-11 w-full rounded-xl">{isSignup ? copy.create : copy.login}<ArrowRight /></Button></form><p className="mt-5 text-center text-sm text-muted-foreground">{isSignup ? "Vous avez déjà un compte ?" : "Pas encore de compte ?"} <button onClick={() => setLocation(isSignup ? "/connexion" : "/inscription")} className="font-semibold text-amber-600 hover:underline">{isSignup ? copy.login : copy.signup}</button></p></CardContent></Card></div></main></PageWrap>;
}

export default function Home() {
  const [location, setLocation] = useLocation();
  const [locale, setLocale] = useState<Locale>(() => (localStorage.getItem("icx-locale") as Locale) || "fr");
  useEffect(() => { document.documentElement.dir = locale === "ar" ? "rtl" : "ltr"; document.documentElement.lang = locale; }, [locale]);
  const updateLocale = (next: Locale) => { setLocale(next); localStorage.setItem("icx-locale", next); document.documentElement.dir = next === "ar" ? "rtl" : "ltr"; document.documentElement.lang = next; };
  const serviceSlug = location.startsWith("/services/") ? location.split("/")[2] : "";
  if (serviceSlug && serviceBySlug[serviceSlug]) return <ServicePage service={serviceBySlug[serviceSlug]} locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/etudes") return <StudiesPage locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/partenaires") return <InfoPage kind="partners" locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/confidentialite") return <InfoPage kind="privacy" locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/mentions-legales") return <InfoPage kind="legal" locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/connexion") return <AuthPageV2 mode="login" locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/inscription") return <AuthPageV2 mode="signup" locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/mon-espace") return <WorkspacePage locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  if (location === "/admin") return <AdminPage locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
  return <HomePage locale={locale} setLocale={updateLocale} setLocation={setLocation} />;
}
